static const float GROUP11_B1[16] = {-1.67822000e-03f, 2.70953099e-03f, 1.38586049e-03f, -2.11583287e-03f, 6.10335264e-04f, 4.14370326e-03f, 7.68858954e-05f, -1.67412194e-03f, -4.91990987e-03f, 2.22410075e-03f, -5.54756727e-03f, -1.18421623e-03f, -4.26090183e-03f, -2.13376037e-03f, 3.00811534e-03f, -9.18663922e-04f};
#define GROUP11_LAYER1_IN 32
#define GROUP11_LAYER1_OUT 16
#define GROUP11_LAYER1_ACT_TANH 1

static const float GROUP11_W2[1][16] = {
  {6.68799430e-02f, 9.28788111e-02f, 1.08975448e-01f, 7.65970051e-02f, -4.46991511e-02f, -7.61941597e-02f, 4.53697406e-02f, -3.39047164e-02f, -1.40542924e-01f, -4.03102413e-02f, -4.15373594e-02f, 1.36383682e-01f, 8.00397024e-02f, -6.84296414e-02f, -1.04461625e-01f, 3.96112762e-02f},
};
static const float GROUP11_B2[1] = {7.45994330e-04f};
#define GROUP11_LAYER2_IN 16
#define GROUP11_LAYER2_OUT 1
#define GROUP11_LAYER2_ACT_IDENTITY 1

static float group11_clip(float x, float lo, float hi) {
  if (x < lo) return lo;
  if (x > hi) return hi;
  return x;
}

static float group11_activation(float x, int act_id) {
  if (act_id == 1) return x > 0.0f ? x : 0.0f;
  if (act_id == 2) return tanhf(x);
  return x;
}

static void group11_dense(const float *in, float *out, const float *w, const float *b, int in_dim, int out_dim, int act_id) {
  int i, j;
  for (i = 0; i < out_dim; i++) {
    float y = b[i];
    for (j = 0; j < in_dim; j++) y += w[i * in_dim + j] * in[j];
    out[i] = group11_activation(y, act_id);
  }
}

static void group11_policy_raw(const float state[8], float raw[1]) {
  float buf0[GROUP11_MAX_WIDTH];
  float buf1[GROUP11_MAX_WIDTH];
  const float *in = state;

  group11_dense(in, buf0, (const float *)GROUP11_W0, GROUP11_B0, GROUP11_LAYER0_IN, GROUP11_LAYER0_OUT, 2);
  in = buf0;

  group11_dense(in, buf1, (const float *)GROUP11_W1, GROUP11_B1, GROUP11_LAYER1_IN, GROUP11_LAYER1_OUT, 2);
  in = buf1;

  group11_dense(in, raw, (const float *)GROUP11_W2, GROUP11_B2, GROUP11_LAYER2_IN, GROUP11_LAYER2_OUT, 0);

}

static void group11_policy_predict(const float state[8], float action[2]) {
  float raw[1];
  float u;
  group11_policy_raw(state, raw);
  raw[0] = group11_clip(raw[0], -1.0f, 1.0f);
  u = raw[0] * GROUP11_U_MAX;
  action[0] = u;
  action[1] = u;
}

/* Compatibility alias for firmware that expects an SB3-style name. */
static void sb3_predict(const float state[8], float action[2]) {
  group11_policy_predict(state, action);
}

